function criteriaBlock(profile) {
  return profile.criteria.map((c) => [
    `- criterion_id: ${c.id}`,
    `  name: ${c.name}`,
    `  covers: ${c.description}`,
    '  anchors:',
    ...['0', '1', '2', '3', '4'].map((k) => `    ${k}: ${c.anchors[k]}`),
