// spans two ADJACENT bullets is still contiguous evidence. Text from non-adjacent lines still fails.
function stripListMarkers(s) {
  return String(s == null ? '' : s).replace(/(^|\n)[ \t]*(?:[-*•▪●·]|\d{1,2}[.)])[ \t]+/g, '$1');
